(()=>{const video=document.querySelector('.home-motion-video'),toggle=document.querySelector('.motion-toggle');if(!video||!toggle)return;const tr=document.documentElement.lang==='tr',reduce=matchMedia('(prefers-reduced-motion: reduce)'),save=navigator.connection?.saveData;let manual=false;function label(){toggle.textContent=video.paused?(tr?'Önizlemeyi oynat':'Play preview'):(tr?'Önizlemeyi duraklat':'Pause preview');toggle.setAttribute('aria-pressed',String(!video.paused))}function play(){if(!video.getAttribute('src'))video.src=video.dataset.src;video.play().catch(label)}video.addEventListener('play',label);video.addEventListener('pause',label);toggle.addEventListener('click',()=>{manual=true;video.paused?play():video.pause()});const observer=new IntersectionObserver(entries=>{const visible=entries[0].isIntersecting;if(!visible)video.pause();else if(!manual&&!reduce.matches&&!save&&!document.hidden)play()},{threshold:.35});observer.observe(video);document.addEventListener('visibilitychange',()=>{if(document.hidden)video.pause()});document.querySelector('.film-dialog')?.addEventListener('close',()=>label());document.querySelectorAll('[data-video-src]').forEach(button=>button.addEventListener('click',()=>video.pause()));reduce.addEventListener('change',()=>{if(reduce.matches)video.pause()})})();
